opencode.config_snippet:
{
  "$schema": "https://opencode.ai/config.json",
  "model": "vllm-docker/ornith-1.5-9b",
  "plugins": ["-opencode.provider.vllm"],
  "agents": {
    "title": { "model": "vllm-docker/ornith-1.5-9b#none" },
    "compaction": { "model": "vllm-docker/ornith-1.5-9b#none" }
  },
  "compaction": { "auto": true, "keep": { "tokens": 12000 }, "buffer": "20%" },
  "providers": {
    "vllm-docker": {
      "name": "vLLM (Docker)",
      "package": "@opencode/ai/providers/openai-compatible",
      "settings": {
        "baseURL": "http://127.0.0.1:8000/v1",
        "apiKey": "{env:VLLM_API_KEY}",
        "headerTimeout": 600000
      },
      "compatibility": { "reasoningField": "reasoning" },
      "models": {
        "ornith-1.5-9b": {
          "modelID": "ornith-1.5-9b",
          "name": "Ornith-1.5-9B NVFP4 (vLLM, thinking toggle)",
          "capabilities": { "tools": true, "input": ["text"], "output": ["text"], "reasoning": { "supported": true } },
          "limit": { "context": 131072, "output": 16384 },
          "variants": [
            { "id": "thinking", "body": { "chat_template_kwargs": { "enable_thinking": true } } },
            { "id": "none", "body": { "chat_template_kwargs": { "enable_thinking": false } } }
          ]
        },
        "gemma-4-12b": {
          "modelID": "gemma-4-12b",
          "name": "Gemma 4 12B QAT W4A16 (vLLM, thinking toggle)",
          "capabilities": { "tools": true, "input": ["text"], "output": ["text"], "reasoning": { "supported": true } },
          "limit": { "context": 131072, "output": 16384 },
          "variants": [
            { "id": "thinking", "body": { "chat_template_kwargs": { "enable_thinking": true } } },
            { "id": "none", "body": { "chat_template_kwargs": { "enable_thinking": false } } }
          ]
        },
        "gpt-oss-20b": {
          "modelID": "gpt-oss-20b",
          "name": "gpt-oss-20b (vLLM, effort low/medium/high)",
          "capabilities": { "tools": true, "input": ["text"], "output": ["text"], "reasoning": { "supported": true, "effort": ["low", "medium", "high"] } },
          "limit": { "context": 65536, "output": 16384 }
        }
      }
    }
  }
}
